//! Small real raw/controller/product controls. Fixtures issue raw acquisitions;
//! the actual driver/indenter/primary perform every traversal and EOF decision.
use super::*;use dm_syntax::{OriginalDeclarationHeaderObserver,OriginalPrimaryHeader,OriginalHeaderFlow,OriginalPrimaryLiveHeader};
use crate::{SourceAcquisitionLease,OriginalRawOpenDecision,OriginalRawReadOutcome,OriginalRawAllocationPlan};
use std::{path::PathBuf,sync::{Mutex,atomic::{AtomicUsize,Ordering}},any::Any};
struct Memory{files:BTreeMap<PathBuf,SourceAcquisitionLease>,opened:Mutex<Vec<PathBuf>>,probed:Mutex<Vec<PathBuf>>}
impl Memory{fn new(files:&[(&str,&str)])->Self{Self{files:files.iter().map(|(path,text)|(PathBuf::from(path),SourceAcquisitionLease::from_raw_original_bytes(text.as_bytes().to_vec(),17u64))).collect(),opened:Mutex::new(Vec::new()),probed:Mutex::new(Vec::new())}}}
impl SourceProvider for Memory{
 fn initial_environment(&self)->InitialEnvironment{InitialEnvironment::OriginalChecker0290}
 fn read(&self,_:&Path)->Result<String,String>{panic!("actual Original never requests ordinary preparation")}
 fn path_presence_admitted(&self,path:&Path,_:&dyn SourceArenaWork)->io::Result<bool>{self.probed.lock().unwrap().push(path.to_path_buf());Ok(self.files.contains_key(path))}
 fn original_raw_source_open_admitted(&self,path:&Path,_:usize,_:&dyn SourceArenaWork,after:&mut dyn FnMut()->io::Result<OriginalRawOpenDecision>,_:&mut dyn FnMut(usize)->io::Result<()>,decode:&mut dyn FnMut(OriginalRawAllocationPlan<'_>)->io::Result<()>,acquired:&mut dyn FnMut(&SourceAcquisitionLease)->io::Result<()>)->io::Result<OriginalRawReadOutcome>{
  self.opened.lock().unwrap().push(path.to_path_buf());let Some(source)=self.files.get(path)else{return Ok(OriginalRawReadOutcome::SourceOpenFailed(io::ErrorKind::NotFound.into()))};if after()?==OriginalRawOpenDecision::Suppress{return Ok(OriginalRawReadOutcome::Suppressed)}decode(OriginalRawAllocationPlan::new(&[],0,0,0,false,false))?;acquired(source)?;Ok(OriginalRawReadOutcome::Acquired(source.clone()))
 }
 fn original_source_bytes<'a>(&'a self,lease:&'a SourceAcquisitionLease)->io::Result<Option<&'a[u8]>>{if !self.files.values().any(|actual|actual.same_original_acquisition(lease)){return Err(io::ErrorKind::InvalidInput.into())}Ok(Some(lease.source_text().as_bytes()))}
}
struct Credit{bytes:AtomicUsize,live:Arc<AtomicUsize>}
impl Drop for Credit{fn drop(&mut self){self.live.fetch_sub(self.bytes.load(Ordering::Acquire),Ordering::AcqRel);}}
impl crate::source_arena_credit::SourceArenaCreditOwner for Credit{fn as_any(&self)->&dyn Any{self}fn reserved_bytes(&self)->usize{self.bytes.load(Ordering::Acquire)}fn visit_storage(&self,_:&mut dyn FnMut(usize,usize)){}}
struct Work{live:Arc<AtomicUsize>}
impl SourceArenaWork for Work{
 fn original_read_bookkeeping_bytes(&self)->io::Result<usize>{Ok(0)}
 fn checkpoint(&self)->io::Result<()>{Ok(())}
 fn reserve(&self,n:usize)->io::Result<crate::source_arena_credit::SourceArenaCredit>{self.live.fetch_add(n,Ordering::AcqRel);Ok(crate::source_arena_credit::SourceArenaCredit::from_resource_owner(Arc::new(Credit{bytes:AtomicUsize::new(n),live:Arc::clone(&self.live)})))}
 fn grow(&self,c:&mut crate::source_arena_credit::SourceArenaCredit,n:usize)->io::Result<()>{let own=c.owner().as_any().downcast_ref::<Credit>().ok_or(io::ErrorKind::InvalidInput)?;if !Arc::ptr_eq(&self.live,&own.live){return Err(io::ErrorKind::InvalidInput.into())}own.bytes.fetch_add(n,Ordering::AcqRel);self.live.fetch_add(n,Ordering::AcqRel);Ok(())}
 fn shrink(&self,c:&mut crate::source_arena_credit::SourceArenaCredit,n:usize)->io::Result<()>{let own=c.owner().as_any().downcast_ref::<Credit>().ok_or(io::ErrorKind::InvalidInput)?;if !Arc::ptr_eq(&self.live,&own.live){return Err(io::ErrorKind::InvalidInput.into())}own.bytes.fetch_update(Ordering::AcqRel,Ordering::Acquire,|old|old.checked_sub(n)).map_err(|_|io::ErrorKind::InvalidInput)?;self.live.fetch_sub(n,Ordering::AcqRel);Ok(())}
}
struct Consumer;impl OriginalDeclarationHeaderObserver for Consumer{fn header(&mut self,_:OriginalPrimaryHeader<'_>)->io::Result<OriginalHeaderFlow>{Ok(OriginalHeaderFlow::Continue)}}
impl OriginalPrimaryStreamConsumer for Consumer{fn callable(&mut self,_:OriginalPrimaryLiveHeader,_:&mut dyn super::super::OriginalFormalTokenStream)->io::Result<OriginalHeaderFlow>{panic!("this raw traversal fixture has no callable declaration")}}
fn omissions()->GenerationOmissions{GenerationOmissions::probe([], &mut |_|panic!("empty explicit output roster"),&mut |_|Ok(())).unwrap()}
#[test]fn real_lazy_controller_runs_include_define_pop_and_publishes_same_literal_binding_and_raw_mapping(){
 let provider=Memory::new(&[("E:/controller/main.dme","#define VALUE 3\n#include \"child.dm\"\n#undef VALUE\n/datum/root\n    var/value = VALUE\n"),("E:/controller/child.dm","#define VALUE 7\n/datum/child\n    var/value = VALUE\n")]);let work=Work{live:Arc::new(AtomicUsize::new(0))};let syntax=Arc::new(AtomicUsize::new(0));let a=SettingAdmission::new(&syntax,64<<20,&||Ok(()));
 let product=GenerationDirectivePlan::prepare_original_checker_stream_using(Path::new("E:/controller/main.dme"),&provider,&BTreeMap::new(),omissions(),1<<20,&work,&a,&mut Consumer).unwrap();assert_eq!(product.delivery(),OriginalDemandDelivery::CheckerLazy0290);assert!(product.expanded().text.as_str().contains('7'));assert!(product.expanded().text.as_str().contains('3'));assert!(product.expanded().origins.len()>0);let(plan,expanded,primary,binding)=product.into_diagnostic_parts_using(&a).unwrap();assert_eq!(plan.occurrences().len(),2);assert!(plan.original_notices().iter().any(|notice|notice.error_type==Some("macro_redefined")));assert_eq!(provider.opened.lock().unwrap().as_slice(),[PathBuf::from("E:/controller/main.dme"),PathBuf::from("E:/controller/child.dm")]);assert!(plan.source_line_starts().is_empty(),"no eager line walk over unread body" );drop((plan,expanded,primary,binding));assert_eq!(syntax.load(Ordering::Acquire),0);assert_eq!(work.live.load(Ordering::Acquire),0);
}
#[test]fn real_controller_duplicate_still_opens_before_suppression_and_nontext_only_probes_metadata(){
 let provider=Memory::new(&[("E:/controller/main.dme","#include \"child.dm\"\n#include \"child.dm\"\n#include \"map.dmm\"\n/datum/root\n"),("E:/controller/child.dm","/datum/child\n"),("E:/controller/map.dmm","this must not be read as source")]);let work=Work{live:Arc::new(AtomicUsize::new(0))};let syntax=Arc::new(AtomicUsize::new(0));let a=SettingAdmission::new(&syntax,64<<20,&||Ok(()));let product=GenerationDirectivePlan::prepare_original_checker_stream_using(Path::new("E:/controller/main.dme"),&provider,&BTreeMap::new(),omissions(),1<<20,&work,&a,&mut Consumer).unwrap();let(plan,expanded,primary,binding)=product.into_diagnostic_parts_using(&a).unwrap();assert_eq!(provider.opened.lock().unwrap().iter().filter(|path|path.ends_with("child.dm")).count(),2);assert!(!provider.opened.lock().unwrap().iter().any(|path|path.ends_with("map.dmm")));let notice=plan.original_notices().iter().find(|notice|notice.error_type==Some("duplicate_include")).unwrap();assert_eq!(notice.notes.count(),1);assert!(plan.items().iter().any(|item|matches!(item,super::super::OrderedItem::NonText{kind:super::super::NonTextKind::Map,..})));drop((plan,expanded,primary,binding));assert_eq!(syntax.load(Ordering::Acquire),0);assert_eq!(work.live.load(Ordering::Acquire),0);
}

#[test]fn genuine_empty_and_lf_raw_sources_keep_real_final_newline_locations(){
 for(text,line)in[("",1),("\n",2)]{let provider=Memory::new(&[("E:/controller/empty.dme",text)]);let work=Work{live:Arc::new(AtomicUsize::new(0))};let syntax=Arc::new(AtomicUsize::new(0));let a=SettingAdmission::new(&syntax,64<<20,&||Ok(()));let product=GenerationDirectivePlan::prepare_original_checker_stream_using(Path::new("E:/controller/empty.dme"),&provider,&BTreeMap::new(),omissions(),1<<20,&work,&a,&mut Consumer).unwrap();assert_eq!(product.expanded().text.as_str(),";\n");assert_eq!(product.expanded().origins.len(),1);let(_,point,_,_,_)=product.expanded().origins.original_raw_point_geometry(0).unwrap();assert_eq!((point.line,point.byte_column),(line,1));let(plan,expanded,primary,binding)=product.into_diagnostic_parts_using(&a).unwrap();assert_eq!(plan.occurrences().len(),1);assert!(plan.original_notices().is_empty());drop((plan,expanded,primary,binding));assert_eq!(syntax.load(Ordering::Acquire),0);assert_eq!(work.live.load(Ordering::Acquire),0);}
}

#[test]fn actual_empty_condition_records_old_first_term_failure_at_hash_and_keeps_endif_balanced(){let provider=Memory::new(&[("E:/controller/empty-condition.dme","#if\n/datum/disabled\n#endif\n/datum/after\n")]);let work=Work{live:Arc::new(AtomicUsize::new(0))};let syntax=Arc::new(AtomicUsize::new(0));let a=SettingAdmission::new(&syntax,64<<20,&||Ok(()));let product=GenerationDirectivePlan::prepare_original_checker_stream_using(Path::new("E:/controller/empty-condition.dme"),&provider,&BTreeMap::new(),omissions(),1<<20,&work,&a,&mut Consumer).unwrap();let(plan,expanded,primary,binding)=product.into_diagnostic_parts_using(&a).unwrap();let notices=plan.original_notices().iter().collect::<Vec<_>>();assert_eq!(notices.len(),1);assert_eq!(notices[0].message,"got EOF, expected one of: operator, literal, variable, proc call");assert!(matches!(notices[0].place,super::super::OriginalNoticePlace::Actual{line:1,column:1,..}));assert!(!expanded.text.as_str().contains("disabled"));assert!(expanded.text.as_str().contains("after"));drop(notices);drop((plan,expanded,primary,binding));assert_eq!(syntax.load(Ordering::Acquire),0);assert_eq!(work.live.load(Ordering::Acquire),0);}

#[test]fn actual_else_and_real_eof_keep_completed_conditional_ranges(){let provider=Memory::new(&[("E:/controller/ranges.dme","#if 0\n/datum/no\n#else\n/datum/yes\n#endif\n#if 1\n/datum/open\n")]);let work=Work{live:Arc::new(AtomicUsize::new(0))};let syntax=Arc::new(AtomicUsize::new(0));let a=SettingAdmission::new(&syntax,64<<20,&||Ok(()));let product=GenerationDirectivePlan::prepare_original_checker_stream_using(Path::new("E:/controller/ranges.dme"),&provider,&BTreeMap::new(),omissions(),1<<20,&work,&a,&mut Consumer).unwrap();let(plan,expanded,primary,binding)=product.into_diagnostic_parts_using(&a).unwrap();let ranges=plan.conditional_ranges().collect::<Vec<_>>();assert_eq!(ranges.len(),3);assert_eq!(ranges.iter().map(|range|range.active).collect::<Vec<_>>(),[false,true,true]);assert_eq!(plan.original_notices().iter().filter(|notice|notice.message=="unterminated #if/#ifdef").count(),1);drop(ranges);drop((plan,expanded,primary,binding));assert_eq!(syntax.load(Ordering::Acquire),0);assert_eq!(work.live.load(Ordering::Acquire),0);}

#[test]fn actual_lazy_callable_stop_retains_open_conditional_without_inventing_history_or_eof_notice(){struct Stop;impl OriginalDeclarationHeaderObserver for Stop{fn header(&mut self,_:OriginalPrimaryHeader<'_>)->io::Result<OriginalHeaderFlow>{Ok(OriginalHeaderFlow::Continue)}}impl OriginalPrimaryStreamConsumer for Stop{fn callable(&mut self,_:OriginalPrimaryLiveHeader,_:&mut dyn super::super::OriginalFormalTokenStream)->io::Result<OriginalHeaderFlow>{Ok(OriginalHeaderFlow::Stop)}}let provider=Memory::new(&[("E:/controller/stopped-range.dme","#if 1\n/datum/proc/prefix(x)\n    BODY\n")]);let work=Work{live:Arc::new(AtomicUsize::new(0))};let syntax=Arc::new(AtomicUsize::new(0));let a=SettingAdmission::new(&syntax,64<<20,&||Ok(()));let product=GenerationDirectivePlan::prepare_original_checker_stream_using(Path::new("E:/controller/stopped-range.dme"),&provider,&BTreeMap::new(),omissions(),1<<20,&work,&a,&mut Stop).unwrap();let(plan,expanded,primary,binding)=product.into_diagnostic_parts_using(&a).unwrap();assert!(plan.conditional_ranges().next().is_none(),"a parser stop is not source EOF or a completed conditional interval");assert!(!plan.original_notices().iter().any(|notice|notice.message=="unterminated #if/#ifdef"));assert!(!expanded.text.as_str().contains("BODY"));drop((plan,expanded,primary,binding));assert_eq!(syntax.load(Ordering::Acquire),0);assert_eq!(work.live.load(Ordering::Acquire),0);}

#[test]fn actual_raw_controller_keeps_indented_procedure_body_inside_real_braces(){struct Body;impl OriginalDeclarationHeaderObserver for Body{fn header(&mut self,_:OriginalPrimaryHeader<'_>)->io::Result<OriginalHeaderFlow>{Ok(OriginalHeaderFlow::Continue)}}impl OriginalPrimaryStreamConsumer for Body{fn callable(&mut self,_:OriginalPrimaryLiveHeader,source:&mut dyn super::super::OriginalFormalTokenStream)->io::Result<OriginalHeaderFlow>{for expected in ["var","/","static","/","A","=","1",")"]{let actual=source.next_header_token()?.ok_or(io::ErrorKind::UnexpectedEof)?;assert_eq!(actual.text,expected);}Ok(OriginalHeaderFlow::Continue)}}let provider=Memory::new(&[("E:/controller/body.dme","/proc/p(var/static/A=1)\n    return A\n")]);let work=Work{live:Arc::new(AtomicUsize::new(0))};let syntax=Arc::new(AtomicUsize::new(0));let a=SettingAdmission::new(&syntax,64<<20,&||Ok(()));let product=GenerationDirectivePlan::prepare_original_checker_stream_using(Path::new("E:/controller/body.dme"),&provider,&BTreeMap::new(),omissions(),1<<20,&work,&a,&mut Body).unwrap();let text=product.expanded().text.as_str();assert!(text.contains("{\nreturn A;\n}\n"),"actual produced body must retain indentation: {text:?}");drop(product);assert_eq!(syntax.load(Ordering::Acquire),0);assert_eq!(work.live.load(Ordering::Acquire),0);}

#[test]fn actual_nested_define_in_condition_dispatches_on_same_raw_cursor_and_preserves_enclosing_completion(){let provider=Memory::new(&[("E:/controller/nested-condition.dme","#if #define VALUE 1\nVALUE\n/datum/yes\n#endif\n/datum/after\n")]);let work=Work{live:Arc::new(AtomicUsize::new(0))};let syntax=Arc::new(AtomicUsize::new(0));let a=SettingAdmission::new(&syntax,64<<20,&||Ok(()));let product=GenerationDirectivePlan::prepare_original_checker_stream_using(Path::new("E:/controller/nested-condition.dme"),&provider,&BTreeMap::new(),omissions(),1<<20,&work,&a,&mut Consumer).unwrap();let(plan,expanded,primary,binding)=product.into_diagnostic_parts_using(&a).unwrap();assert!(!expanded.text.as_str().contains("yes"));assert!(expanded.text.as_str().contains("after"));let notices=plan.original_notices().iter().collect::<Vec<_>>();assert_eq!(notices.len(),1);assert_eq!(notices[0].message,"got '\n', expected one of: operator, literal, variable, proc call");assert!(matches!(notices[0].place,super::super::OriginalNoticePlace::Actual{line:1,column:5,..}));drop(notices);assert_eq!(plan.conditional_ranges().count(),1);assert!(plan.final_macros().contains_key("VALUE"));drop((plan,expanded,primary,binding));assert_eq!(syntax.load(Ordering::Acquire),0);assert_eq!(work.live.load(Ordering::Acquire),0);}
#[test]fn nested_directive_stack_resource_refusal_is_operational_and_never_source_false_recovery(){let provider=Memory::new(&[("E:/controller/nested-resource.dme","#if #define VALUE 1\nVALUE\n/datum/yes\n#endif\n")]);let work=Work{live:Arc::new(AtomicUsize::new(0))};let syntax=Arc::new(AtomicUsize::new(0));let a=SettingAdmission::with_stack_allowance(&syntax,64<<20,32*1024,&||Ok(()));let error=GenerationDirectivePlan::prepare_original_checker_stream_using(Path::new("E:/controller/nested-resource.dme"),&provider,&BTreeMap::new(),omissions(),1<<20,&work,&a,&mut Consumer).err().expect("actual root plus outer control consume two frames; nested control exceeds them");assert_eq!(error.kind(),io::ErrorKind::OutOfMemory);assert_eq!(syntax.load(Ordering::Acquire),0);assert_eq!(work.live.load(Ordering::Acquire),0);}

