#[test]fn actual_script_includes_retain_order_duplicates_and_paths_without_opening_payload(){let provider=Memory::new(&[("E:/controller/scripts.dme","#include \"one.dms\"\n#include \"two.dms\"\n#include \"one.dms\"\n/datum/after\n"),("E:/controller/one.dms","SCRIPT_BYTES_MUST_NOT_OPEN"),("E:/controller/two.dms","OTHER_SCRIPT_BYTES")]);let work=Work{live:Arc::new(AtomicUsize::new(0))};let syntax=Arc::new(AtomicUsize::new(0));let a=SettingAdmission::new(&syntax,64<<20,&||Ok(()));let product=GenerationDirectivePlan::prepare_original_checker_stream_using(Path::new("E:/controller/scripts.dme"),&provider,&BTreeMap::new(),omissions(),1<<20,&work,&a,&mut Consumer).unwrap();let(plan,expanded,primary,binding)=product.into_diagnostic_parts_using(&a).unwrap();let scripts=plan.script_includes().collect::<Vec<_>>();assert_eq!(scripts.iter().map(|(path,_)|path.file_name().unwrap().to_str().unwrap()).collect::<Vec<_>>(),["one.dms","two.dms","one.dms"]);for(index,(_,place))in scripts.iter().enumerate(){assert!(matches!(place,super::super::OriginalNoticePlace::Actual{line,..}if *line==index+1));}assert_eq!(*provider.opened.lock().unwrap(),[PathBuf::from("E:/controller/scripts.dme")]);assert!(!expanded.text.as_str().contains("SCRIPT_BYTES"));drop(scripts);drop((plan,expanded,primary,binding));assert_eq!(syntax.load(Ordering::Acquire),0);assert_eq!(work.live.load(Ordering::Acquire),0);}

#[test]fn actual_root_open_observer_sees_only_typed_initial_open_failure_and_precedes_real_read(){struct Observe{before:AtomicUsize,failed:AtomicUsize,stop:bool}impl super::OriginalRootOpenObserver for Observe{fn before_root_read_using(&self,_:&dyn SourceProvider,_:&Path,_:&dyn SourceArenaWork,_:&SettingAdmission<'_>)->io::Result<()>{self.before.fetch_add(1,Ordering::AcqRel);if self.stop{Err(io::Error::from_raw_os_error(1450))}else{Ok(())}}fn actual_root_open_failed_using(&self,failed:super::OriginalRootOpenFailureLoan<'_,'_>){assert_eq!(failed.error().kind(),io::ErrorKind::NotFound);assert_eq!(failed.path(),Path::new("E:/controller/missing.dme"));self.failed.fetch_add(1,Ordering::AcqRel);}}let work=Work{live:Arc::new(AtomicUsize::new(0))};let syntax=Arc::new(AtomicUsize::new(0));let a=SettingAdmission::new(&syntax,64<<20,&||Ok(()));for stop in [false,true]{let provider=Memory::new(&[]);let observer=Observe{before:AtomicUsize::new(0),failed:AtomicUsize::new(0),stop};let error=GenerationDirectivePlan::prepare_original_checker_stream_observing_root_using(Path::new("E:/controller/missing.dme"),&provider,&BTreeMap::new(),omissions(),1<<20,&work,&a,&mut Consumer,&observer).err().unwrap();assert_eq!(observer.before.load(Ordering::Acquire),1);assert_eq!(observer.failed.load(Ordering::Acquire),usize::from(!stop));assert_eq!(provider.opened.lock().unwrap().len(),usize::from(!stop));if stop{assert_eq!(error.raw_os_error(),Some(1450))}else{assert_eq!(error.kind(),io::ErrorKind::NotFound)}}assert_eq!(syntax.load(Ordering::Acquire),0);assert_eq!(work.live.load(Ordering::Acquire),0);}

