#[test]fn actual_condition_template_admission_deadline_and_quota_never_become_source_notice(){use std::cell::Cell;let raw="#if \"prefix[1+1]suffix\"\n/datum/disabled\n#endif\n/datum/after\n";let used=Arc::new(AtomicUsize::new(0));let work=Work{live:Arc::new(AtomicUsize::new(0))};let calls=Cell::new(0usize);let peak=Cell::new(0usize);{let provider=Memory::new(&[("E:/controller/template-budget.dme",raw)]);let checkpoint=||{calls.set(calls.get()+1);peak.set(peak.get().max(used.load(Ordering::Acquire)));Ok(())};let a=SettingAdmission::new(&used,64<<20,&checkpoint);drop(GenerationDirectivePlan::prepare_original_checker_stream_using(Path::new("E:/controller/template-budget.dme"),&provider,&BTreeMap::new(),omissions(),1<<20,&work,&a,&mut Consumer).unwrap());}assert_eq!(used.load(Ordering::Acquire),0);assert_eq!(work.live.load(Ordering::Acquire),0);assert!(calls.get()>3&&peak.get()>0);for stop_at in[1,calls.get()/2,calls.get()-1]{let provider=Memory::new(&[("E:/controller/template-budget.dme",raw)]);let count=Cell::new(0usize);let checkpoint=||{count.set(count.get()+1);if count.get()>=stop_at{Err(io::Error::from_raw_os_error(1450))}else{Ok(())}};let a=SettingAdmission::new(&used,64<<20,&checkpoint);let error=GenerationDirectivePlan::prepare_original_checker_stream_using(Path::new("E:/controller/template-budget.dme"),&provider,&BTreeMap::new(),omissions(),1<<20,&work,&a,&mut Consumer).err().unwrap();assert_eq!(error.raw_os_error(),Some(1450));assert_eq!(used.load(Ordering::Acquire),0);assert_eq!(work.live.load(Ordering::Acquire),0);}let provider=Memory::new(&[("E:/controller/template-budget.dme",raw)]);let a=SettingAdmission::new(&used,peak.get()-1,&||Ok(()));let error=GenerationDirectivePlan::prepare_original_checker_stream_using(Path::new("E:/controller/template-budget.dme"),&provider,&BTreeMap::new(),omissions(),1<<20,&work,&a,&mut Consumer).err().unwrap();assert_eq!(error.kind(),io::ErrorKind::OutOfMemory);assert_eq!(used.load(Ordering::Acquire),0);assert_eq!(work.live.load(Ordering::Acquire),0);}

